import "dotenv/config";
import { db } from "../src/lib/db";
import { billingConfig } from "../src/lib/billing/config";
import { recoverBilling, reconcileBilling } from "../src/lib/billing/jobs";
import { sweepSubscriptionLifecycle } from "../src/lib/subscription-maintenance";

async function main() {
  const [command, ...extra] = process.argv.slice(2);
  if (extra.length || !["recover", "reconcile", "sweep"].includes(command))
    throw new Error("Use recover, reconcile, or sweep.");
  if (command === "sweep") {
    await sweepSubscriptionLifecycle();
    console.info(JSON.stringify({ command, complete: true }));
    return;
  }
  // A scheduled command must report broken configuration instead of silently
  // succeeding while billing recovery is disabled.
  billingConfig();
  if (command === "reconcile") {
    await reconcileBilling();
    return;
  }
  const result = await recoverBilling();
  if ("disabled" in result) throw new Error("BILLING_RECOVERY_DISABLED");
  const failed =
    result.failed +
    result.checkoutFailures +
    (result.inbox && "pending" in result.inbox
      ? (result.inbox.pending ?? 0)
      : 0);
  console.info(JSON.stringify({ command, ...result, complete: failed === 0 }));
  if (failed) process.exitCode = 1;
}

void main()
  .catch(() => {
    // Provider errors may contain sensitive payloads. Emit only a fixed code.
    console.error("SUBSCRIPTION_MAINTENANCE_FAILED");
    process.exitCode = 1;
  })
  .finally(() => db.$disconnect());
